}
for (const kind of ['memory', 'firestore']) {
  test("'`${kind}: signed two-chat claims transfer once atomically with contexts and real lineage`, async () => {
    const f = fixture(kind); await open(f, 4); // ceil(sqrt(4)) = 2
    const offer = f.chatRequest('"'"'!offer'"', source, '111');
    await Promise.all(Array.from({ length: 12 }, () => f.apps[source].dispatch(offer)));
    await f.chat('"'!offer'"', source, '112'); await f.chat('"'!accept'"', target, '211');
    assert.equal((await f.state.getKeeperRegistry()).holderId, source);
    const accept = f.chatRequest('"'!accept'"', target, '212');
    await Promise.all(Array.from({ length: 12 }, () => f.apps[source].dispatch(accept)));
    const registry = await f.state.getKeeperRegistry(); assert.equal(registry.holderId, target);
    assert.equal(registry.pendingHop.finalized, true); assert.equal(registry.send, undefined);
    const journey = await f.state.getPublicJourney(); assert.equal(journey.rings, 1);
    assert.equal(journey.stops[0].raidSize, 4); assert.equal(journey.stops[0].ringIndex, 1);
    assert.equal((await f.state.getPrivateMarks(source, { broadcasterId: source, chatterId: source })).context.holdsRelic, false);
    assert.equal((await f.state.getPrivateMarks(target, { broadcasterId: target, chatterId: target })).context.holdsRelic, true);
    assert.ok("'!JSON.stringify(journey).includes('"'chatterId')); assert.ok("'!JSON.stringify(journey).includes('"'offers'));
    // A second signed, eligible manual hop back. No finalized intent blocks it.
    f.advance(1000);
    await f.apps[source].dispatch(f.request(target, 'channel.raid', { from_broadcaster_user_id: target, to_broadcaster_user_id: source, viewers: 1 }, { condition: { from_broadcaster_user_id: target } }));
    await f.chat('"'!offer'"', target, '333'); await f.chat('"'!accept'"', source, '444');
    assert.equal((await f.state.getKeeperRegistry()).holderId, source);
    assert.equal((await f.state.getPublicJourney()).rings, 2);
  });
  test("'`${kind}: wrong side, same user, bot and forged channel never supply claim proof`, async () => {
    const f = fixture(kind); await open(f);
    await f.chat('"'"'!accept'"', source, '555'); await f.chat('"'!offer'"', target, '555');
    await f.chat('"'!offer'"', source, bot); await f.chat('"'!accept'"', target, bot);
    assert.equal((await f.state.getKeeperRegistry()).pendingHop.offers.length, 0);
    await f.chat('"'!offer'"', source, '111'); await f.chat('"'!accept'"', target, '111');
    assert.equal((await f.state.getKeeperRegistry()).holderId, source);
    const forged = f.request('777', 'channel.chat.message', { broadcaster_user_id: '777', chatter_user_id: '222', message_id: 'forged', message: { text: '"'!accept'"', fragments: [] } });
    assert.equal((await f.apps[source].dispatch(forged)).status, 400);
    await f.chat('"'!accept'"', target, '222'); assert.equal((await f.state.getKeeperRegistry()).holderId, target);
  });
  test("'`${kind}: threshold uses only bounded signed viewers and caps at ten per side`, async () => {
    const f = fixture(kind); await open(f, 1000000);
    assert.equal((await f.state.getKeeperRegistry()).pendingHop.threshold, 10);
    for (let i = 0; i < 10; i++) await f.chat('"'"'!offer'"', source, String(100 + i));
    for (let i = 0; i < 9; i++) await f.chat('"'!accept'"', target, String(200 + i));
    assert.equal((await f.state.getKeeperRegistry()).holderId, source);
    await f.chat('"'!accept'"', target, '209'); assert.equal((await f.state.getPublicJourney()).rings, 1);
    for (const viewers of [-1, 1.2, 1000001, '10']) {
