      const service = createMarkService(f.state, { now: f.now }); const actor = { broadcasterId: source, chatterId: source };
      if (action === 'forget') await service.forgetMe(source, { broadcasterId: source, chatterId: '333' });
      if (action === 'block') await service.blockUser(source, actor, '333');
      if (action === 'veto') { await service.vetoLast(source, actor); await service.vetoLast(source, actor); }
      if (action === 'opt-out') await service.optOut(source, actor);
      text = JSON.stringify(await f.state.getPublicJourney()); assert.ok("'!text.includes('"'moon'), action);
      assert.equal((await f.state.getPublicJourney()).rings, 1);
    }
  });
